#include "PresetStore.h"

#include <algorithm>

// The embedded factory bank, generated by juce_add_binary_data from `presets/*.xml`.
// See the CMakeLists for the target that produces it.
#include <MiXXPresets.h>

namespace mixxynth
{
    namespace
    {
        constexpr const char* presetExtension = ".xml";

        // Where a preset whose filename has no " - " in it lands. Not an error: a file
        // someone dropped into the folder by hand should still show up in the list.
        constexpr const char* otherCategory = "Other";

        // Where a category sits in the display order. Anything not named in the curated
        // order comes after everything that is.
        int categoryRank (const juce::String& category)
        {
            const auto& order = presetCategoryOrder();
            const int index = order.indexOf (category);

            return index >= 0 ? index : order.size();
        }
    }

    const juce::StringArray& presetCategoryOrder()
    {
        static const juce::StringArray order { "Bass", "Lead", "Keys", "Bell",
                                               "Pluck", "Pad", "Sequence", "FX" };
        return order;
    }

    void PresetStore::splitName (const juce::String& fileNameWithoutExtension,
                                 juce::String& category, juce::String& name)
    {
        const juce::String full = fileNameWithoutExtension.trim();
        const int sep = full.indexOf (presetNameSeparator);

        if (sep < 0)
        {
            category = otherCategory;
            name = full;
            return;
        }

        category = full.substring (0, sep).trim();
        name = full.substring (sep + juce::String (presetNameSeparator).length()).trim();

        // "Bell - .xml" is a name, not a category: fall back rather than listing a preset
        // with an empty name that cannot be picked out of the list.
        if (category.isEmpty())
            category = otherCategory;

        if (name.isEmpty())
        {
            name = full;
            category = otherCategory;
        }
    }

    PresetStore::PresetStore()
    {
        refresh();
    }

    int PresetStore::size() const
    {
        const juce::ScopedLock sl (lock);

        return static_cast<int> (presets.size());
    }

    const PresetInfo* PresetStore::rawAt (int index) const
    {
        return index >= 0 && index < static_cast<int> (presets.size())
                   ? &presets[static_cast<size_t> (index)]
                   : nullptr;
    }

    PresetInfo PresetStore::at (int index) const
    {
        const juce::ScopedLock sl (lock);
        const auto* info = rawAt (index);

        return info != nullptr ? *info : PresetInfo();
    }

    bool PresetStore::isValidIndex (int index) const
    {
        const juce::ScopedLock sl (lock);

        return rawAt (index) != nullptr;
    }

    bool PresetStore::isFactory (int index) const
    {
        const juce::ScopedLock sl (lock);
        const auto* info = rawAt (index);

        return info != nullptr && info->factory;
    }

    juce::String PresetStore::nameOf (int index) const
    {
        const juce::ScopedLock sl (lock);
        const auto* info = rawAt (index);

        return info != nullptr ? info->name : juce::String();
    }

    juce::String PresetStore::categoryOf (int index) const
    {
        const juce::ScopedLock sl (lock);
        const auto* info = rawAt (index);

        return info != nullptr ? info->category : juce::String();
    }

    juce::File PresetStore::userPresetDir()
    {
        return juce::File::getSpecialLocation (juce::File::userApplicationDataDirectory)
                   .getChildFile ("MiXXynth")
                   .getChildFile ("Presets");
    }

    juce::File PresetStore::fileFor (const juce::String& category, const juce::String& name)
    {
        // Through createLegalFileName because the name comes from a text box: a name with a
        // colon or a slash in it would otherwise write outside the preset folder, and using
        // the same helper on both sides means the file that is written is the file that is
        // found again.
        const juce::String leaf = juce::File::createLegalFileName (category.trim()
                                                                       + presetNameSeparator
                                                                       + name.trim());

        return userPresetDir().getChildFile (leaf + presetExtension);
    }

    void PresetStore::refresh()
    {
        const juce::ScopedLock sl (lock);

        presets.clear();
        listFactory();
        listUser();

        // One ordering for the whole list: the curated category order, then the category
        // name, then factory before user within a category, then the preset's own name.
        // Sorting the two sources together rather than concatenating them is what puts a
        // category's factory and user presets in one place.
        std::stable_sort (presets.begin(), presets.end(),
                          [] (const PresetInfo& a, const PresetInfo& b)
                          {
                              const int ra = categoryRank (a.category);
                              const int rb = categoryRank (b.category);

                              if (ra != rb)                 return ra < rb;
                              if (a.category != b.category) return a.category < b.category;
                              if (a.factory != b.factory)   return a.factory;

                              return a.name < b.name;
                          });
    }

    void PresetStore::listFactory()
    {
        // Every resource in the preset data target is a preset, so there is nothing to
        // filter: the resource list IS the bank. That also means a preset added to
        // `presets/` cannot be forgotten here, because there is nothing here to forget.
        for (int i = 0; i < MiXXPresets::namedResourceListSize; ++i)
        {
            PresetInfo info;
            info.factory = true;
            info.resource = MiXXPresets::namedResourceList[i];

            const juce::String fileName (MiXXPresets::originalFilenames[i]);
            splitName (fileName.upToLastOccurrenceOf (".", false, false), info.category, info.name);

            presets.push_back (info);
        }
    }

    void PresetStore::listUser()
    {
        const auto dir = userPresetDir();

        if (! dir.isDirectory())
            return;

        for (const auto& entry : juce::RangedDirectoryIterator (dir, false, "*.xml"))
        {
            PresetInfo info;
            info.file = entry.getFile();
            info.factory = false;

            splitName (info.file.getFileNameWithoutExtension(), info.category, info.name);

            presets.push_back (info);
        }
    }

    int PresetStore::indexOf (const juce::String& category, const juce::String& name) const
    {
        const juce::ScopedLock sl (lock);

        int found = -1;

        for (int i = 0; i < static_cast<int> (presets.size()); ++i)
        {
            const auto& info = presets[static_cast<size_t> (i)];

            if (info.category != category || info.name != name)
                continue;

            // Factory wins a tie, so a name that exists in both resolves to the one that
            // cannot be overwritten.
            if (info.factory)
                return i;

            found = i;
        }

        return found;
    }

    juce::ValueTree PresetStore::read (int index) const
    {
        const juce::ScopedLock sl (lock);
        const auto* info = rawAt (index);

        if (info == nullptr)
            return {};

        if (info->factory)
        {
            int bytes = 0;
            const char* data = MiXXPresets::getNamedResource (info->resource.toRawUTF8(), bytes);

            if (data == nullptr || bytes <= 0)
                return {};

            // The explicit length matters: the embedded bytes are not null-terminated, so
            // treating them as a C string would read past the end of the resource.
            if (auto xml = juce::parseXML (juce::String (data, static_cast<size_t> (bytes))))
                return juce::ValueTree::fromXml (*xml);

            return {};
        }

        if (auto xml = juce::parseXML (info->file))
            return juce::ValueTree::fromXml (*xml);

        return {};
    }

    int PresetStore::save (const juce::String& category, const juce::String& name,
                           const juce::ValueTree& state)
    {
        if (name.trim().isEmpty() || ! state.isValid())
            return -1;

        const juce::ScopedLock sl (lock);

        // Saving over a factory preset is refused, and so is saving UNDER a factory name:
        // the bank lives in the binary, so an overwrite would be a lie, and a second preset
        // with the same name would leave no way to tell which one the list meant. Overwriting
        // one of your own presets is allowed, because that is what Save is for.
        const int existing = indexOf (category.trim(), name.trim());

        if (existing >= 0 && isFactory (existing))
            return -1;

        const auto file = fileFor (category, name);

        if (! file.getParentDirectory().createDirectory())
            return -1;

        auto xml = state.createXml();

        if (xml == nullptr || ! xml->writeTo (file, {}))
            return -1;

        refresh();

        return indexOf (category.trim(), name.trim());
    }

    bool PresetStore::remove (int index)
    {
        const juce::ScopedLock sl (lock);
        const auto* info = rawAt (index);

        if (info == nullptr || info->factory)
            return false;

        if (! info->file.deleteFile())
            return false;

        refresh();

        return true;
    }

    juce::StringArray PresetStore::categories() const
    {
        const juce::ScopedLock sl (lock);

        juce::StringArray result;

        // The list is already in display order, so first-seen is the order to show them in.
        for (const auto& p : presets)
            if (! result.contains (p.category))
                result.add (p.category);

        return result;
    }

    int PresetStore::numFactory() const
    {
        const juce::ScopedLock sl (lock);

        return static_cast<int> (std::count_if (presets.begin(), presets.end(),
                                                [] (const PresetInfo& p) { return p.factory; }));
    }

    int PresetStore::numUser() const
    {
        const juce::ScopedLock sl (lock);

        return static_cast<int> (presets.size())
                 - static_cast<int> (std::count_if (presets.begin(), presets.end(),
                                                    [] (const PresetInfo& p) { return p.factory; }));
    }

    juce::ValueTree overlayState (const juce::ValueTree& base, const juce::ValueTree& overlay)
    {
        if (! base.isValid())
            return overlay.createCopy();

        if (! overlay.isValid())
            return base.createCopy();

        auto result = base.createCopy();

        for (int i = 0; i < overlay.getNumProperties(); ++i)
        {
            const auto name = overlay.getPropertyName (i);
            result.setProperty (name, overlay.getProperty (name), nullptr);
        }

        for (int i = 0; i < overlay.getNumChildren(); ++i)
        {
            const auto child = overlay.getChild (i);

            if (child.hasType (presetState::parameterNode))
            {
                // Keyed by id, because every parameter node shares the type "PARAM".
                const auto id = child.getProperty (presetState::idProperty);
                auto target = result.getChildWithProperty (presetState::idProperty, id);

                if (target.isValid())
                    target.setProperty (presetState::valueProperty,
                                        child.getProperty (presetState::valueProperty), nullptr);
                else
                    result.appendChild (child.createCopy(), nullptr);

                continue;
            }

            // Anything else - the shapes, the FX files - replaces wholesale by type. Merging
            // shape children point by point would be a way to load half of one patch's
            // modulation into the middle of another's.
            result.removeChild (result.getChildWithName (child.getType()), nullptr);
            result.appendChild (child.createCopy(), nullptr);
        }

        return result;
    }

    juce::ValueTree diffState (const juce::ValueTree& full, const juce::ValueTree& init)
    {
        if (! full.isValid())
            return {};

        auto result = juce::ValueTree (full.getType());

        for (int i = 0; i < full.getNumProperties(); ++i)
        {
            const auto name = full.getPropertyName (i);

            if (init.isValid() && init.hasProperty (name)
                  && full.getProperty (name).toString() == init.getProperty (name).toString())
                continue;

            result.setProperty (name, full.getProperty (name), nullptr);
        }

        for (int i = 0; i < full.getNumChildren(); ++i)
        {
            const auto child = full.getChild (i);

            if (child.hasType (presetState::parameterNode))
            {
                const auto id = child.getProperty (presetState::idProperty);
                const auto base = init.getChildWithProperty (presetState::idProperty, id);
                const auto value = child.getProperty (presetState::valueProperty);

                // A tolerance rather than exact equality, because the two sides reach this
                // point by different routes and a parameter that reads back as 0.30000001 must
                // not be written into every preset as though the user had moved it.
                if (base.isValid()
                      && std::abs (static_cast<float> (value)
                                     - static_cast<float> (base.getProperty (presetState::valueProperty))) < 1.0e-6f)
                    continue;

                result.appendChild (child.createCopy(), nullptr);
                continue;
            }

            // A child is carried when the init patch does not have one of that name, or has one
            // that differs. The comparison is the fingerprint, so it is the same question asked
            // in the same way as the dirty marker rather than a second, subtly different one.
            const auto base = init.getChildWithName (child.getType());

            if (base.isValid() && fingerprint (base) == fingerprint (child))
                continue;

            result.appendChild (child.createCopy(), nullptr);
        }

        return result;
    }

    juce::int64 fingerprint (const juce::ValueTree& tree)
    {
        if (! tree.isValid())
            return 0;

        // Values are QUANTISED before hashing, to six significant digits, and that is not
        // tidiness - it is what makes the dirty marker trustworthy.
        //
        // A parameter stores a normalised value, so writing 4000 Hz into a state tree and
        // reading it back can give 4000.0005. Hash the raw floats and loading a preset can light
        // the dirty dot by itself, and a patch that reports itself as edited when nobody
        // touched it is a marker people learn to ignore. Six significant digits is far finer
        // than any control's step and far coarser than that drift.
        auto quantised = [] (const juce::var& v)
        {
            const double d = static_cast<double> (v);

            if (std::abs (d) < 1.0e-12)
                return juce::String ("0");

            const double magnitude = std::pow (10.0, 6.0 - std::ceil (std::log10 (std::abs (d))));

            return juce::String (std::round (d * magnitude) / magnitude);
        };

        // FNV-1a over the tree, with properties visited in NAME order so two trees holding
        // the same patch hash the same whatever order their properties went in. That matters
        // because the two things being compared are built by different code paths: one by
        // apvts.copyState() and one by XML that was parsed back off disk.
        juce::uint64 hash = 14695981039346656037ULL;

        auto mix = [&hash] (const juce::String& text)
        {
            for (const auto c : text)
            {
                hash ^= static_cast<juce::uint64> (static_cast<unsigned char> (c));
                hash *= 1099511628211ULL;
            }
        };

        mix (tree.getType().toString());

        juce::StringArray names;

        for (int i = 0; i < tree.getNumProperties(); ++i)
            names.add (tree.getPropertyName (i).toString());

        names.sort (true);

        for (const auto& n : names)
            mix (n + "=" + quantised (tree.getProperty (juce::Identifier (n))));

        for (int i = 0; i < tree.getNumChildren(); ++i)
        {
            mix ("|");
            mix (juce::String (fingerprint (tree.getChild (i))));
        }

        return static_cast<juce::int64> (hash);
    }
}
